async function md5Digest(data){const src=data instanceof Uint8Array?data:new Uint8Array(data),len=((src.length+8>>>6)+1)*64,b=new Uint8Array(len);b.set(src);b[src.length]=128;const dv=new DataView(b.buffer);dv.setUint32(len-8,(src.length*8)>>>0,true);dv.setUint32(len-4,Math.floor(src.length*8/4294967296),true);const shifts=[7,12,17,22,5,9,14,20,4,11,16,23,6,10,15,21],K=Array.from({length:64},(_,i)=>Math.floor(Math.abs(Math.sin(i+1))*4294967296)>>>0);let a0=0x67452301,b0=0xefcdab89,c0=0x98badcfe,d0=0x10325476;for(let off=0;off<len;off+=64){const M=Array.from({length:16},(_,i)=>dv.getUint32(off+i*4,true));let a=a0,bv=b0,c=c0,d=d0;for(let i=0;i<64;i++){let f,g,s;if(i<16){f=(bv&c)|(~bv&d);g=i;s=shifts[i%4]}else if(i<32){f=(d&bv)|(~d&c);g=(5*i+1)%16;s=shifts[4+i%4]}else if(i<48){f=bv^c^d;g=(3*i+5)%16;s=shifts[8+i%4]}else{f=c^(bv|~d);g=(7*i)%16;s=shifts[12+i%4]}const x=(a+f+K[i]+M[g])>>>0,rot=(x<<s)|(x>>>(32-s));a=d;d=c;c=bv;bv=(bv+rot)>>>0}a0=(a0+a)>>>0;b0=(b0+bv)>>>0;c0=(c0+c)>>>0;d0=(d0+d)>>>0}return [a0,b0,c0,d0].map(n=>[0,8,16,24].map(k=>((n>>>k)&255).toString(16).padStart(2,'0')).join('')).join('')}

async function digest(slug,s,file){let data=file?await file.arrayBuffer():new TextEncoder().encode(s);let alg=slug.includes('sha512')?'SHA-512':slug.includes('sha1')?'SHA-1':'SHA-256';if(slug==='hash-md5')return await md5Digest(new Uint8Array(data));let h=await crypto.subtle.digest(alg,data);return [...new Uint8Array(h)].map(x=>x.toString(16).padStart(2,'0')).join('')}

async function loadPluginScript(src){if([...document.scripts].some(x=>x.src===src))return;await new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.onload=resolve;el.onerror=()=>reject(Error('Plugin formatter gagal dimuat dari CDN.'));document.head.append(el);});}
async function formatCode(s,kind,minify=false){
 const prettier=await loadLib('https://cdn.jsdelivr.net/npm/prettier@3.3.3/standalone.js','prettier');
 for(const [url,key] of [
  ['https://cdn.jsdelivr.net/npm/prettier@3.3.3/plugins/html.js','html'],
  ['https://cdn.jsdelivr.net/npm/prettier@3.3.3/plugins/babel.js','babel'],
  ['https://cdn.jsdelivr.net/npm/prettier@3.3.3/plugins/postcss.js','postcss']
 ]) if(!window.prettierPlugins?.[key]) await loadPluginScript(url);
 const parser=kind==='html'?'html':kind==='css'?'css':'babel';
 const pluginKeys=kind==='html'?['html']:kind==='css'?['postcss']:['babel'];
 const plugins=pluginKeys.map(k=>window.prettierPlugins[k]).filter(Boolean);
 if(!minify) return await prettier.format(s,{parser,plugins,printWidth:100,tabWidth:2,semi:true,singleQuote:true});
 if(kind==='html') return s.replace(/<!--[\s\S]*?-->/g,'').replace(/>\s+</g,'><').replace(/\s{2,}/g,' ').trim();
 if(kind==='css') return s.replace(/\/\*[\s\S]*?\*\//g,'').replace(/\s*([{}:;,])\s*/g,'$1').replace(/;}/g,'}').trim();
 const terser=await loadLib('https://cdn.jsdelivr.net/npm/terser@5.31.6/dist/bundle.min.js','Terser');
 const out=await terser.minify(s);
 if(out.error)throw out.error;
 return out.code;
}
