async function runCollage(files){
 if(files.length<2)throw Error('Pilih minimal dua foto.');const imgs=await Promise.all(files.map(f=>createImageBitmap(f))),cell=320,cols=Math.ceil(Math.sqrt(imgs.length)),rows=Math.ceil(imgs.length/cols),canvas=document.createElement('canvas');canvas.width=cols*cell;canvas.height=rows*cell;const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,canvas.width,canvas.height);
 imgs.forEach((im,i)=>{const x=i%cols*cell,y=Math.floor(i/cols)*cell,s=Math.max(cell/im.width,cell/im.height),w=im.width*s,h=im.height*s;c.save();c.beginPath();c.rect(x,y,cell,cell);c.clip();c.drawImage(im,x+(cell-w)/2,y+(cell-h)/2,w,h);c.restore()});
 const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.92)),u=URL.createObjectURL(blob);$('previewArea').innerHTML=`<img alt="Kolase" src="${u}">`;show('previewArea');result('Kolase selesai dibuat.','kolase.jpg',blob);
}
async function runPalette(file){
 if(!file)throw Error('Pilih foto.');const img=await createImageBitmap(file),c=document.createElement('canvas');c.width=96;c.height=96;const x=c.getContext('2d',{willReadFrequently:true});x.drawImage(img,0,0,96,96);const d=x.getImageData(0,0,96,96).data,m=new Map();for(let i=0;i<d.length;i+=16){const h=[d[i],d[i+1],d[i+2]].map(v=>Math.min(255,Math.round(v/32)*32).toString(16).padStart(2,'0')).join('').toUpperCase();m.set(h,(m.get(h)||0)+1)}const colors=[...m].sort((a,b)=>b[1]-a[1]).slice(0,8).map(x=>'#'+x[0]);$('previewArea').innerHTML=`<div class="palette-grid">${colors.map(v=>`<div class="palette-swatch" style="background:${v}"><span>${v}</span></div>`).join('')}</div>`;show('previewArea');result(colors.join('\n'),'palet-warna.txt',new Blob([colors.join('\n')],{type:'text/plain'}));
}

document.addEventListener('change',e=>{if(e.target?.id==='fileInput'&&['hapus-objek','hapus-orang','hapus-teks-foto','hapus-watermark','hapus-latar'].includes(activeTool?.slug))setupManualEditor(e.target.files?.[0]);});

document.addEventListener('click',e=>{let c=e.target.closest('[data-category]');if(c){openCategory(c.dataset.category);return}let t=e.target.closest('[data-tool]');if(t){openTool(t.dataset.tool);hide('searchResults');return}let h=e.target.closest('[data-gohome]');if(h){home();document.getElementById(h.dataset.gohome)?.scrollIntoView({behavior:'smooth'});return}});
$('backHome').onclick=home;$('backCategory').onclick=()=>openCategory(activeCategory);$('categorySearch').addEventListener('input',e=>renderCategory(e.target.value));$('globalSearch').addEventListener('input',e=>{let q=e.target.value.trim(),box=$('searchResults');if(!q){hide('searchResults');return}box.innerHTML=tools.filter(t=>(t.name+' '+t.description).toLowerCase().includes(q.toLowerCase())).slice(0,24).map(card).join('')||'<p class="muted">Tidak ditemukan.</p>';show('searchResults')});$('homeLink').onclick=e=>{e.preventDefault();home()};$('processBtn').onclick=run;$('resetBtn').onclick=()=>{let i=$('input'),f=$('fileInput');if(i)i.value='';if(f)f.value='';$('output').value='';$('status').textContent='';hide('resultArea');hide('previewArea');lastBlob=null};$('copyBtn').onclick=async()=>{try{await navigator.clipboard.writeText($('output').value);toast('Hasil disalin')}catch{toast('Clipboard tidak tersedia di konteks ini')}};$('downloadBtn').onclick=()=>{let b=lastBlob||new Blob([$('output').value],{type:'text/plain;charset=utf-8'});downloadBlob(b,lastName||'hasil.txt')};$('themeBtn').onclick=()=>{document.body.classList.toggle('light');localStorage.setItem('dafzz-theme',document.body.classList.contains('light')?'light':'dark')};if(localStorage.getItem('dafzz-theme')==='light')document.body.classList.add('light');
fetch('./tools.json').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(data=>{tools=data;renderHome();if(data.length!==300)toast(`Peringatan: katalog memuat ${data.length} tool`) }).catch(e=>{$('categoryGrid').textContent='Katalog gagal dimuat. Jalankan melalui localhost atau hosting HTTPS.';console.error(e)});if('serviceWorker'in navigator&&location.protocol.startsWith('http'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.warn));
